						goto case 9;

					case 12:
						// Digit
						r = Recognize_Digit(text, p, ref failure);

						if (r < 0)
							goto case 1;

						p = r;
						goto case 10;

					case 13:
						// '-'
						if (p + 1 > text.Length)
							goto case 1;
						if (text[p + 0] != '-')
							goto case 1;
						p += 1;
						goto case 11;

					case 14:
						// Digit{4} — stop, and check the count
						c2 = saved;

						if (c2 < 4)
							goto case 1;

						goto case 13;

					case 15:
						// Digit{4} — take another, or leave stopping open
						if (c2 >= 4)
						{
							saved = c2;
							goto case 14;
						}

						if (sp + 3 > bt.Length) bt = Grow(bt);
						bt[sp] = 14; bt[sp + 1] = p; bt[sp + 2] = c2; sp += 3;
						goto case 18;

					case 16:
						// Digit{4} — one more taken
						c2++;
						goto case 15;

					case 17:
						// Digit{4} — start counting
						c2 = 0;
						goto case 15;

					case 18:
						// Digit
						r = Recognize_Digit(text, p, ref failure);

						if (r < 0)
							goto case 1;

						p = r;
						goto case 16;

					default:
						return -1;
				}
			}
		}

		// Amount = '-'? & Digit+ & ('.' & Digit{2})?
		static int Recognize_Amount(global::System.ReadOnlySpan<char> text, int pos, ref Failure failure)
		{
			global::System.Span<int> bt = stackalloc int[48];

			var sp    = 0;
			var saved = 0;
			var p     = pos;
			var r     = 0;
			var c0    = 0;
			var c1    = 0;
			var c2    = 0;
			var c3    = 0;
			var state = 20;

			while (true)
			{
				switch (state)
				{
					case 0:
						return p;

					case 1:
						if (p > failure.Position)
							failure.Position = p;

						if (sp == 0)
							return -1;

						sp    -= 3;
						state  = bt[sp];
						p      = bt[sp + 1];
						saved  = bt[sp + 2];

						// The one transition whose target is not known until now,
						// and so the one that goes through the switch again.
						continue;

					case 2:
						// ('.' & Digit{2})? — stop, and check the count
						c0 = saved;

						goto case 0;

					case 3:
						// ('.' & Digit{2})? — take another, or leave stopping open
						if (c0 >= 1)
						{
							saved = c0;
							goto case 2;
						}

						if (sp + 3 > bt.Length) bt = Grow(bt);
						bt[sp] = 2; bt[sp + 1] = p; bt[sp + 2] = c0; sp += 3;
						goto case 11;

					case 4:
						// ('.' & Digit{2})? — one more taken
						c0++;
						goto case 3;

					case 5:
						// ('.' & Digit{2})? — start counting
						c0 = 0;
						goto case 3;

					case 6:
						// Digit{2} — stop, and check the count
						c1 = saved;

						if (c1 < 2)
							goto case 1;

						goto case 4;

					case 7:
						// Digit{2} — take another, or leave stopping open
						if (c1 >= 2)
						{
							saved = c1;
							goto case 6;
						}

						if (sp + 3 > bt.Length) bt = Grow(bt);
						bt[sp] = 6; bt[sp + 1] = p; bt[sp + 2] = c1; sp += 3;
						goto case 10;

					case 8:
						// Digit{2} — one more taken
						c1++;
						goto case 7;

					case 9:
						// Digit{2} — start counting
						c1 = 0;
						goto case 7;

					case 10:
						// Digit
						r = Recognize_Digit(text, p, ref failure);

						if (r < 0)
							goto case 1;

						p = r;
						goto case 8;

					case 11:
						// '.'
						if (p + 1 > text.Length)
							goto case 1;
						if (text[p + 0] != '.')
							goto case 1;
						p += 1;
						goto case 9;

					case 12:
						// Digit+ — stop, and check the count
						c2 = saved;

						if (c2 < 1)
							goto case 1;

						goto case 5;

					case 13:
						// Digit+ — take another, or leave stopping open
						if (sp + 3 > bt.Length) bt = Grow(bt);
						bt[sp] = 12; bt[sp + 1] = p; bt[sp + 2] = c2; sp += 3;
						goto case 16;

					case 14:
						// Digit+ — one more taken
						c2++;
						goto case 13;

					case 15:
						// Digit+ — start counting
						c2 = 0;
						goto case 13;

					case 16:
						// Digit
						r = Recognize_Digit(text, p, ref failure);

						if (r < 0)
							goto case 1;

						p = r;
						goto case 14;

					case 17:
						// '-'? — stop, and check the count
						c3 = saved;

						goto case 15;

					case 18:
						// '-'? — take another, or leave stopping open
						if (c3 >= 1)
						{
							saved = c3;
							goto case 17;
						}

						if (sp + 3 > bt.Length) bt = Grow(bt);
						bt[sp] = 17; bt[sp + 1] = p; bt[sp + 2] = c3; sp += 3;
						goto case 21;

					case 19:
						// '-'? — one more taken
						c3++;
						goto case 18;

					case 20:
						// '-'? — start counting
						c3 = 0;
						goto case 18;

					case 21:
						// '-'
						if (p + 1 > text.Length)
							goto case 1;
						if (text[p + 0] != '-')
							goto case 1;
						p += 1;
						goto case 19;

					default:
						return -1;
				}
			}
		}

		// Name = [^ '\n' | '\r' | '|']+
		static int Recognize_Name(global::System.ReadOnlySpan<char> text, int pos, ref Failure failure)
		{
			global::System.Span<int> bt = stackalloc int[48];

			var sp    = 0;
			var saved = 0;
			var p     = pos;
			var c     = '\0';
			var c0    = 0;
			var state = 5;

			while (true)
			{
				switch (state)
				{
					case 0:
						return p;

					case 1:
						if (p > failure.Position)
							failure.Position = p;

						if (sp == 0)
							return -1;

						sp    -= 3;
						state  = bt[sp];
						p      = bt[sp + 1];
						saved  = bt[sp + 2];

						// The one transition whose target is not known until now,
						// and so the one that goes through the switch again.
						continue;

					case 2:
						// [^ '\n' | '\r' | '|']+ — stop, and check the count
						c0 = saved;

						if (c0 < 1)
							goto case 1;

						goto case 0;

					case 3:
						// [^ '\n' | '\r' | '|']+ — take another, or leave stopping open
						if (sp + 3 > bt.Length) bt = Grow(bt);
						bt[sp] = 2; bt[sp + 1] = p; bt[sp + 2] = c0; sp += 3;
						goto case 6;

					case 4:
						// [^ '\n' | '\r' | '|']+ — one more taken
						c0++;
						goto case 3;

					case 5:
						// [^ '\n' | '\r' | '|']+ — start counting
						c0 = 0;
						goto case 3;

					case 6:
						// [^ '\n' | '\r' | '|']
						if (p >= text.Length)
							goto case 1;

						c = text[p];

						if (!!(c == '\n' || c == '\r' || c == '|'))
							goto case 1;

						p++;
						goto case 4;

					default:
						return -1;
				}
			}
		}

		// the lookahead [^ ]
		static int Recognize_eof_Look0(global::System.ReadOnlySpan<char> text, int pos)
		{
			var p     = pos;
			var state = 2;

			switch (state)
			{
				case 0:
					return p;

				case 1:
					return -1;

				case 2:
					// [^ ]
					if (p >= text.Length)
						goto case 1;
					p++;
					goto case 0;

				default:
					return -1;
			}
		}

		// eof = ?![^ ]
		static int Recognize_eof(global::System.ReadOnlySpan<char> text, int pos, ref Failure failure)
		{
			var p     = pos;
			var state = 2;

			switch (state)
			{
				case 0:
					return p;

				case 1:
					if (p > failure.Position)
						failure.Position = p;

					return -1;

				case 2:
					// ?![^ ]
					if (Recognize_eof_Look0(text, p) < 0)
						goto case 0;
					goto case 1;

				default:
					return -1;
			}
		}

		// eol = ("\u000D\u000A" | '\n' | '\r')
		static int Recognize_eol(global::System.ReadOnlySpan<char> text, int pos, ref Failure failure)
		{
			global::System.Span<int> bt = stackalloc int[48];

			var sp    = 0;
			var saved = 0;
			var p     = pos;
			var state = 6;

			while (true)
			{
				switch (state)
				{
					case 0:
						return p;

					case 1:
						if (p > failure.Position)
							failure.Position = p;

						if (sp == 0)
							return -1;

						sp    -= 3;
						state  = bt[sp];
						p      = bt[sp + 1];
						saved  = bt[sp + 2];

						// The one transition whose target is not known until now,
						// and so the one that goes through the switch again.
						continue;

					case 2:
						// '\r'
						if (p + 1 > text.Length)
							goto case 1;
						if (text[p + 0] != '\r')
							goto case 1;
						p += 1;
						goto case 0;

					case 3:
						// '\n'
						if (p + 1 > text.Length)
							goto case 1;
						if (text[p + 0] != '\n')
							goto case 1;
						p += 1;
						goto case 0;

					case 4:
						// '\n' — try this one, or the next
						if (sp + 3 > bt.Length) bt = Grow(bt);
						bt[sp] = 2; bt[sp + 1] = p; bt[sp + 2] = 0; sp += 3;
						goto case 3;

					case 5:
						// "\u000D\u000A"
						if (p + 2 > text.Length)
							goto case 1;
						if (text[p + 0] != '\r')
							goto case 1;
						if (text[p + 1] != '\n')
							goto case 1;
						p += 2;
						goto case 0;

					case 6:
						// "\u000D\u000A" — try this one, or the next
						if (sp + 3 > bt.Length) bt = Grow(bt);
						bt[sp] = 4; bt[sp + 1] = p; bt[sp + 2] = 0; sp += 3;
						goto case 5;

					default:
						return -1;
				}
			}
		}

		/// <summary>What a publication answers with: the value, or why there is none.</summary>
		public readonly struct Match<T>
			where T : class
		{
			private Match(bool isSuccess, T? value, string? error, int position, int length)
			{
				IsSuccess = isSuccess;
				Value     = value;
				Error     = error;
				Position  = position;
				Length    = length;
			}

			/// <summary>Whether there is a value.</summary>
			public bool IsSuccess { get; }

			/// <summary>What was recognized, or null.</summary>
			public T? Value { get; }

			/// <summary>Why nothing was recognized, or null.</summary>
			public string? Error { get; }

			/// <summary>Where the match began, or how far the input could be followed before it failed.</summary>
			public int Position { get; }

			/// <summary>How much was matched. Zero when nothing was.</summary>
			public int Length { get; }

			internal static Match<T> Success(T value, int position, int length)
			{
				return new Match<T>(true, value, null, position, length);
			}

			internal static Match<T> Failed(string error, int position)
			{
				return new Match<T>(false, null, error, position, 0);
			}
		}

		/// <summary>Where a match got before it gave up, and why.</summary>
		struct Failure
		{
			/// <summary>
			/// The furthest position the input was followed to. Zero on a match that
			/// succeeded without ever backtracking, and meaningless unless one failed.
			/// </summary>
			public int Position;
		}

		static int[] Grow(global::System.Span<int> from)
		{
			var bigger = new int[from.Length * 2];

			from.CopyTo(bigger);

			return bigger;
		}
	}
}
